// test_sigguard.cpp — verification of the SigGuard reproduction.
//
// Ground truth:
//  1. SHA-256 known-answer vectors (FIPS 180-4) — the binary's gate uses
//     OpenSSL SHA-256 (FUN_102f8fa5c/8fc08/9109d).
//  2. The packed table blob extracted from the binary
//     (tests/fixtures/sigguard_tables.bin, 0x1830C bytes, SHA-256
//     0b6cdf37...). Header "GYM\x14", 8257 records.
//  3. MAC cross-check vectors generated by an independent Python
//     transcription of the decompiled expansion (FUN_1014bd6aa/73a/81c).
//  4. Structural invariants of the expanded tables (zero rows for n=0).
//  5. Verdict-code mapping (accept 0/1/2; reject 3..9; bit-30 clear set).
//  6. Synthetic trailers exercising the verifier's mode chain and rejection
//     paths. A valid mode-1 trailer cannot be forged without solving the
//     table MAC, so the accept path is tested with verify_mac disabled and
//     the MAC path is tested through its rejection verdict (code 7).
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "rbxvm/sigguard.hpp"

using namespace rbxvm;

static int g_failures = 0;
#define CHECK(cond, ...)                                     \
    do {                                                     \
        if (!(cond)) {                                       \
            ++g_failures;                                    \
            std::printf("FAIL: %s:%d: ", __FILE__, __LINE__);\
            std::printf(__VA_ARGS__);                        \
            std::printf("\n");                              \
        }                                                    \
    } while (0)

static std::vector<uint8_t> readFile(const char* path) {
    FILE* f = std::fopen(path, "rb");
    if (!f) return {};
    std::vector<uint8_t> data;
    uint8_t buf[65536];
    size_t n;
    while ((n = std::fread(buf, 1, sizeof buf, f)) > 0) data.insert(data.end(), buf, buf + n);
    std::fclose(f);
    return data;
}

static std::string hex(const uint8_t* p, size_t n) {
    static const char* d = "0123456789abcdef";
    std::string s;
    for (size_t i = 0; i < n; ++i) { s += d[p[i] >> 4]; s += d[p[i] & 15]; }
    return s;
}

static void testSha256() {
    CHECK(sigguard::sha256Hex(nullptr, 0) ==
              "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
          "sha256 empty");
    const char* abc = "abc";
    CHECK(sigguard::sha256Hex(reinterpret_cast<const uint8_t*>(abc), 3) ==
              "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
          "sha256 abc");
    const char* fox = "The quick brown fox jumps over the lazy dog";
    CHECK(sigguard::sha256Hex(reinterpret_cast<const uint8_t*>(fox), std::strlen(fox)) ==
              "d7a8fbb307d7809469ca9abcb0082e4f8d5651e46d3cdb762d02d0bf37c9e592",
          "sha256 fox");
}

static bool loadTables(sigguard::Tables& t) {
    std::vector<uint8_t> blob = readFile("tests/fixtures/sigguard_tables.bin");
    if (blob.size() != sigguard::kPackedTableBytes) return false;
    if (!sigguard::loadPackedTables(t, blob.data(), blob.size())) return false;
    sigguard::expandTables(t);
    return true;
}

static void testTables(const sigguard::Tables& t) {
    CHECK(t.t1.size() == 8257, "T1 record count");
    CHECK(t.a.size() == 0x1000 && t.b.size() == 0x1000, "A/B sizes");
    CHECK(t.c.size() == 0x3c000, "C size");
    for (size_t i = 0; i < 16; ++i) {
        const sigguard::Record zero{};
        CHECK(t.a[i * 256] == zero, "A row 0 zero (i=%zu)", i);
        CHECK(t.b[i * 256] == zero, "B row 0 zero (i=%zu)", i);
    }
    // T1[0] is the MAC initial state (the blob header is 12 bytes).
    CHECK(hex(t.t1[0].data(), 12) == "47594d14d92f8980d42fb840", "T1[0] initial state");
}

static void testMacVectors(const sigguard::Tables& t) {
    struct Case { const char* sel; const char* want; };
    static const Case cases[] = {
        {"00000000000000000000000000000000", "47594d14d92f8980d42fb840"},
        {"000102030405060708090a0b0c0d0e0f", "713efdb10db11c600856ad84"},
        {"11111111111111111111111111111111", "a06182a4a53c3d83d01f9f62"},
    };
    for (const Case& c : cases) {
        uint8_t sel[16];
        for (int i = 0; i < 16; ++i) {
            unsigned v = 0;
            std::sscanf(c.sel + 2 * i, "%2x", &v);
            sel[i] = uint8_t(v);
        }
        auto mac = sigguard::computeMac(t, sel);
        CHECK(hex(mac.data(), 12) == c.want, "MAC %s: got %s", c.sel,
              hex(mac.data(), 12).c_str());
    }
}

static void testVerdictMapping() {
    for (int code = 0; code <= 9; ++code) {
        const bool reject = code >= 3;
        CHECK(sigguard::codeRejects(code) == reject, "codeRejects(%d)", code);
        const bool clear = code == 3 || code == 4 || code == 6 || code == 7 || code == 9;
        CHECK(sigguard::codeClearsBit30(code) == clear, "codeClearsBit30(%d)", code);
    }
}

// Build a synthetic mode-1 blob: payload (0x100 bytes) + 0x18-byte trailer.
// The trailer's first 4 bytes and bytes 4..8 XOR to 0x74171870; the last 4
// bytes encode the v>0 magic with version byte `version`.
static std::vector<uint8_t> makeMode1Blob(uint8_t version, uint32_t checkword) {
    std::vector<uint8_t> blob(0x100 + 0x18, 0);
    for (size_t i = 0; i < 0x100; ++i) blob[i] = uint8_t(i * 7 + 3);
    uint8_t* tr = blob.data() + 0x100;
    // checkword = u32(tr[0..4]) ^ u32(tr[4..8])
    uint32_t a = checkword;
    std::memcpy(tr, &a, 4);
    // bytes 4..8 = 0 so the checkword is exactly `checkword`
    // encode the v>0 trailer magic at tr[0x14..0x18]:
    tr[0x14] = uint8_t(tr[0] ^ 0x32);
    tr[0x15] = uint8_t(tr[1] ^ 0xC4);
    tr[0x16] = uint8_t(tr[2] ^ 0x6A);
    tr[0x17] = uint8_t(tr[3] ^ version);
    return blob;
}

// Build a synthetic mode-0 blob: payload + 0x28-byte trailer whose secondary
// magic is present (u32(t) ^ u32(t+8) == 0x946AC432) and whose v>0 magic is
// absent, so the mode chain selects 0.
static std::vector<uint8_t> makeMode0Blob() {
    std::vector<uint8_t> blob(0x100 + 0x28, 0x5A);
    uint8_t* tr = blob.data() + 0x100;
    const uint32_t magic = 0x946AC432u;
    std::memcpy(tr, &magic, 4);       // u32(tr) ^ u32(tr+8) = magic
    std::memset(tr + 8, 0, 4);
    // Make sure the v>0 magic check fails (b2 != 0x6A).
    tr[0x14] = 0; tr[0x15] = 0; tr[0x16] = 0; tr[0x17] = 0;
    return blob;
}

static void testVerifier(const sigguard::Tables& t) {
    // Trivial pass: tiny blobs -> code 1 (accept).
    {
        uint8_t small[8] = {1, 2, 3, 4, 5, 6, 7, 8};
        auto r = sigguard::verify(t, small, sizeof small);
        CHECK(r.code == 1 && !r.reject, "tiny blob code 1 accept");
    }

    // Mode 1, correct checkword, MAC mismatch -> code 7.
    {
        auto blob = makeMode1Blob(1, 0x74171870u);
        sigguard::Config cfg;
        auto r = sigguard::verify(t, blob.data(), blob.size(), cfg);
        CHECK(r.mode == sigguard::Mode::V1, "mode 1 detected");
        CHECK(r.checkword == 0x74171870u, "checkword");
        CHECK(r.code == 7 && r.reject && r.clears_bit30, "MAC mismatch code 7");
    }

    // Mode 1 with the MAC check disabled -> code 0 accept.
    {
        auto blob = makeMode1Blob(1, 0x74171870u);
        sigguard::Config cfg;
        cfg.verify_mac = false;
        auto r = sigguard::verify(t, blob.data(), blob.size(), cfg);
        CHECK(r.code == 0 && !r.reject, "MAC-disabled accept code 0");
    }

    // Mode 1 with a bad checkword -> code 9.
    {
        auto blob = makeMode1Blob(1, 0x12345678u);
        auto r = sigguard::verify(t, blob.data(), blob.size());
        CHECK(r.code == 9 && r.reject, "bad checkword code 9");
    }

    // threshold_flag >= 2 makes mode 1 take the simple reject path (code 6).
    {
        auto blob = makeMode1Blob(1, 0x74171870u);
        sigguard::Config cfg;
        cfg.threshold_flag = 2;
        auto r = sigguard::verify(t, blob.data(), blob.size(), cfg);
        CHECK(r.code == 6 && r.reject, "threshold rejects mode 1");
    }

    // Mode 2 -> code 5; mode 3 with max_mode 1 -> code 4.
    {
        auto blob = makeMode1Blob(2, 0x74171870u);
        sigguard::Config cfg;
        cfg.max_mode = 2;
        auto r = sigguard::verify(t, blob.data(), blob.size(), cfg);
        CHECK(r.code == 5 && r.reject, "mode 2 code 5 (mode=%d code=%d)", int(r.mode), r.code);
        blob = makeMode1Blob(3, 0x74171870u);
        r = sigguard::verify(t, blob.data(), blob.size(), cfg);
        CHECK(r.code == 4 && r.reject, "mode > max code 4");
    }

    // Mode 0 requires the v0 secondary magic; it always takes the simple
    // reject path (code 6) because the threshold is >= 1.
    {
        auto blob = makeMode0Blob();
        auto r = sigguard::verify(t, blob.data(), blob.size());
        CHECK(r.mode == sigguard::Mode::V0, "v0 secondary magic -> mode 0");
        CHECK(r.code == 6 && r.reject, "mode 0 code 6");
        // force_signed turns mode 0 into -1 -> code 3.
        sigguard::Config cfg;
        cfg.force_signed = 1;
        r = sigguard::verify(t, blob.data(), blob.size(), cfg);
        CHECK(r.code == 3 && r.reject, "forced mode 0 code 3");
    }

    // No trailer at all -> mode -1 -> code 3.
    {
        std::vector<uint8_t> blob(0x120, 0x5A);
        auto r = sigguard::verify(t, blob.data(), blob.size());
        CHECK(r.mode == sigguard::Mode::ForcedReject, "no trailer -> mode -1");
        CHECK(r.code == 3 && r.reject, "no trailer code 3");
    }
}

int main() {
    testSha256();
    testVerdictMapping();

    sigguard::Tables t;
    if (!loadTables(t)) {
        std::printf("FAIL: cannot load tests/fixtures/sigguard_tables.bin\n");
        return 1;
    }
    testTables(t);
    testMacVectors(t);
    testVerifier(t);

    if (g_failures == 0) {
        std::printf("all sigguard tests passed\n");
        return 0;
    }
    std::printf("%d test failure(s)\n", g_failures);
    return 1;
}
